import re

_LINE = re.compile(
    r'(?P<ip>[0-9a-fA-F:.]+) \S+ (?P<user>\S+) \[(?P<time>[^\]]+)\] '
    r'"(?P<method>[A-Z]+) (?P<path>\S+) HTTP/[0-9.]+" '
    r'(?P<status>[0-9]{3}) (?P<size>[0-9]+|-) '
    r'"(?P<referer>(?:[^"\\]|\\.)*)" "(?P<agent>(?:[^"\\]|\\.)*)"'
)


def _unescape(text):
    return re.sub(r'\\(["\\])', r'\1', text)


def parse_line(line):
    if line.endswith("\r\n"):
        line = line[:-2]
    elif line.endswith("\n"):
        line = line[:-1]
    m = _LINE.fullmatch(line)
    if not m:
        return None
    d = m.groupdict()
    return {
        "ip": d["ip"],
        "user": None if d["user"] == "-" else d["user"],
        "time": d["time"],
        "method": d["method"],
        "path": d["path"],
        "status": int(d["status"]),
        "size": 0 if d["size"] == "-" else int(d["size"]),
        "referer": None if d["referer"] == "-" else _unescape(d["referer"]),
        "agent": _unescape(d["agent"]),
    }


def parse_all(lines):
    records = []
    bad = 0
    for line in lines:
        if not line.strip():
            continue
        rec = parse_line(line)
        if rec is None:
            bad += 1
        else:
            records.append(rec)
    return records, bad

